#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-or-later
"""Generates the FFT twiddle table of src/workloads/fft/spec.hpp.

The table is, for each m, the doubles nearest the real numbers cos(2 pi m / n)
and -sin(2 pi m / n), n = 4096, computed with 120 decimal digits of arithmetic
(mpmath) and rounded once, to nearest, by exact rational arithmetic. The bits
are written, not decimal text, so no reader's float parser stands between the
table and the machine.

Two outputs:
  gen_twiddles.py header   the C++ header of the first octant, m in [0, n/8]
                           (src/workloads/fft/twiddle_table.hpp)
  gen_twiddles.py full     every W[m], m in [0, n), each computed directly from
                           its own angle -- no symmetry used -- as the bits of
                           Re W[m] and Im W[m] (tests/fixtures/fft/twiddles_full.txt):
                           the fixture the tests compare the header-built table to.
The machine and versions that produced the committed outputs are recorded in
tests/fixtures/fft/README.md.
"""

import struct
import sys
from fractions import Fraction

import mpmath

POINTS = 4096
OCTANT = POINTS // 8
TINY = mpmath.mpf(10) ** -100


def nearest_double_bits(value):
    """The bits of the double nearest the mpmath real `value` (no ties arise)."""
    mantissa, exponent = abs(value).man_exp
    exact = Fraction(int(mantissa)) * (Fraction(2) ** exponent)
    if value < 0:
        exact = -exact
    return struct.unpack("<Q", struct.pack("<d", float(exact)))[0]


def angle_of(m):
    return 2 * mpmath.pi * m / POINTS


def header():
    out = sys.stdout
    out.write(
        "// SPDX-License-Identifier: GPL-3.0-or-later\n"
        "#ifndef LOADFORGE_WORKLOADS_FFT_TWIDDLE_TABLE_HPP\n"
        "#define LOADFORGE_WORKLOADS_FFT_TWIDDLE_TABLE_HPP\n\n"
        "// GENERATED by tests/fixtures/fft/gen_twiddles.py header; do not edit by hand.\n"
        "//\n"
        "// Row m holds the IEEE 754 bits of RN(cos(2 pi m / 4096)) and\n"
        "// RN(sin(2 pi m / 4096)) for m in [0, 512], RN the double nearest the real\n"
        "// number (spec.hpp, the twiddle table). Computed offline with 120-digit\n"
        "// arithmetic. The other seven octants are exact images of this one\n"
        "// (twiddle.hpp).\n\n"
        "#include <array>\n#include <cstdint>\n\n"
        "namespace loadforge::workloads::fft {\n\n"
        "struct OctantRow {\n  std::uint64_t cos_bits;\n  std::uint64_t sin_bits;\n};\n\n"
        f"inline constexpr std::array<OctantRow, {OCTANT + 1}> kOctant = {{{{\n"
    )
    for m in range(OCTANT + 1):
        cos_bits = nearest_double_bits(mpmath.cos(angle_of(m)))
        sin_bits = nearest_double_bits(mpmath.sin(angle_of(m)))
        out.write(f"    {{0x{cos_bits:016X}ULL, 0x{sin_bits:016X}ULL}},\n")
    out.write("}};\n\n}  // namespace loadforge::workloads::fft\n\n#endif\n")


def full():
    sys.stdout.write("# W[m] of src/workloads/fft/spec.hpp: m, bits of Re W[m], bits of Im W[m]\n")
    for m in range(POINTS):
        cosine = mpmath.cos(angle_of(m))
        sine = mpmath.sin(angle_of(m))
        # An exact zero is +0.0, never -0.0 (spec.hpp); the computed value is
        # zero to 120 digits exactly when the real number is.
        re_bits = 0 if abs(cosine) < TINY else nearest_double_bits(cosine)
        im_bits = 0 if abs(sine) < TINY else nearest_double_bits(-sine)
        sys.stdout.write(f"{m} {re_bits:016X} {im_bits:016X}\n")


def main(argv):
    mpmath.mp.dps = 120
    if argv == ["header"]:
        header()
    elif argv == ["full"]:
        full()
    else:
        sys.exit("usage: gen_twiddles.py header|full")


main(sys.argv[1:])
